text:
{
  "title_novice": "Сетка скважин: объём важнее площади",
  "summary": [
    {"text": "Скважины в залежи выгоднее размещать так, чтобы они освещали объём залежи, а не её площадь.", "claims": ["c1"]},
    {"text": "Поэтому их сгущают в сводовой части, где основные запасы, а у края разреживают.", "claims": ["c2"]},
    {"text": "Такая сетка даёт надёжные параметры для подсчёта запасов и меньше малоэффективного бурения.", "claims": ["c3", "c4"]}
  ],
  "claims": [
    {"key": "c1", "text": "Автор принимает допущение: более выгодна сетка, которая равномерно освещает объём залежи, а не её площадь.", "kind": "assumption", "unit_id": "u-222-44a115", "page": 222, "quote": "Если исходить из предположения о том, что более выгодной является такая сетка, которая освещала бы равномерно объем, а не площадь залежи", "numbers": [], "question": null},
    {"key": "c2", "text": "При этом допущении скважины целесообразно сгущать в сводовой части залежи и разреживать в краевой.", "kind": "inference", "unit_id": "u-222-44a115", "page": 222, "quote": "целесообразно концентрировать скважины в сводовой части залежи, где сосредоточены основные запасы, и разреживать в краевой", "numbers": [], "question": null},
    {"key": "c3", "text": "В центральной части залежи параметры для подсчёта запасов и проекта разработки получаются более достоверными, так как определены по большему числу скважин.", "kind": "inference", "unit_id": "u-222-44a115", "page": 222, "quote": "для центральной части залежи, содержащей основные запасы, получаются более достоверные, определенные по большому числу скважин параметры для подсчета запасов и составления проекта разработки", "numbers": [], "question": null},
    {"key": "c4", "text": "Бурение приконтурных скважин ограничивают, потому что с точки зрения разведки они малоэффективны.", "kind": "inference", "unit_id": "u-222-44a115", "page": 222, "quote": "ограничивается бурение малоэффективных с точки зрения разведки приконтурных скважин", "numbers": [], "question": null},
    {"key": "c5", "text": "Для последующей разработки скважины у края создают задел в благоприятных условиях по производительности и обводнённости.", "kind": "inference", "unit_id": "u-222-44a115", "page": 222, "quote": "для последующей разработки создается определенный задел скважин, расположенных в благоприятных условиях с точки зрения производительности и обводненности", "numbers": [], "question": null},
    {"key": "c6", "text": "Размещение разведочных скважин рационально планировать, исходя из перечисленных соображений.", "kind": "inference", "unit_id": "u-222-fbecec", "page": 222, "quote": "Размещение разведочных скважин рационально планировать, исходя именно из указанных соображений", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Залежь занимает объём: нефть или газ лежат в толще пород, а не на плоскости.", "claims": [], "hypothesis": true},
    {"text": "Автор принимает допущение: лучшая сетка равномерно освещает объём залежи, а не её площадь.", "claims": ["c1"], "hypothesis": false},
    {"text": "Здесь «освещать» значит давать сведения о. Скважина даёт сведения о породе рядом с собой.", "claims": ["c1"], "hypothesis": true},
    {"text": "Основные запасы сосредоточены в сводовой части. Поэтому скважины там нужны больше всего.", "claims": ["c2"], "hypothesis": false},
    {"text": "Край залежи может занимать много площади, но малую долю объёма (из предыдущего узла n54).", "claims": [], "hypothesis": true},
    {"text": "В центре много скважин, поэтому параметры надёжнее: их определяют по большому числу скважин.", "claims": ["c3"], "hypothesis": false},
    {"text": "Приконтурные скважины для разведки малоэффективны, поэтому их бурение ограничивают.", "claims": ["c4"], "hypothesis": false},
    {"text": "Вывод автора: размещение разведочных скважин планируют по этим соображениям.", "claims": ["c6"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист планирует сетку разведки по трём соображениям: достоверность в центре, меньше лишнего бурения у края, задел для разработки.", "claims": ["c3", "c4", "c5", "c6"], "hypothesis": false},
    {"text": "Признак для решения: где в залежи сводовая часть и где приконтурная зона.", "claims": ["c2"], "hypothesis": true},
    {"text": "Проверка: хватает ли скважин в центре, чтобы оценить параметры для подсчёта запасов.", "claims": ["c3"], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Правило опирается на допущение о цели: освещать объём, а не площадь. При другой цели вывод будет другим.", "claims": ["c1"], "hypothesis": false},
    {"text": "Приконтурные скважины малоэффективны только для разведки. Для разработки они создают задел.", "claims": ["c4", "c5"], "hypothesis": false},
    {"text": "Вывод о достоверности держится на большом числе скважин в центре. Мало скважин — параметры менее надёжны.", "claims": ["c3"], "hypothesis": false},
    {"text": "Текст говорит о массивной залежи. Для пластовых залежей такое правило без проверки применять нельзя.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Как такая сетка выглядит на карте", "text": "На карте скважины густо стоят внутри контура свода и редко у его границы, как точки на изолиниях.", "claims": [], "hypothesis": true}
  ],
  "procedure": [
    {"text": "Найти сводовую часть залежи: там сосредоточены основные запасы.", "claims": ["c2"]},
    {"text": "Сгустить разведочные скважины в сводовой части.", "claims": ["c2"]},
    {"text": "Разредить скважины в приконтурной (краевой) зоне.", "claims": ["c2", "c4"]},
    {"text": "Проверить, что в центре достаточно скважин для параметров подсчёта запасов и проекта разработки.", "claims": ["c3"]},
    {"text": "Спланировать размещение разведочных скважин по этим соображениям.", "claims": ["c6"]}
  ],
  "numbers_conditions": [
    {"text": "Условие применения: цель сетки — освещать объём залежи, а не площадь (допущение автора).", "claims": ["c1"]},
    {"text": "Признак для сгущения скважин: сводовая часть, где сосредоточены основные запасы.", "claims": ["c2"]},
    {"text": "Числовых порогов в тексте узла нет. Критерии качественные: «больше», «меньше», «достоверные».", "claims": []}
  ],
  "terms_defined": [
    {"term": "подсчёт запасов", "term_en": "hydrocarbon reserves estimation", "abbr": "", "definition": "Расчёт того, сколько нефти или газа содержится в залежи. Опирается на параметры, полученные по скважинам.", "claims": ["c3"]},
    {"term": "проект разработки", "term_en": "field development plan", "abbr": "", "definition": "Документ, по которому планируют добычу нефти или газа из месторождения (общее определение, не из книги).", "claims": ["c3"]},
    {"term": "обводнённость", "term_en": "water cut", "abbr": "", "definition": "Доля воды в добываемой жидкости (общее определение). В тексте упомянута как критерий для скважин.", "claims": ["c5"]}
  ],
  "terms_used": ["залежь", "запасы", "сводовая часть залежи", "приконтурная зона", "сетка скважин", "разведка", "разведочная скважина", "объём залежи", "площадь залежи", "массивная залежь", "производительность скважины", "задел скважин", "разработка"],
