  "misconception": {"pack_id": null, "wrong": "Скважины надо расставлять ровной сеткой по площади, как точки на карте.", "right": "Залежь — это объём, а основные запасы лежат в своде. Поэтому скважины сгущают в центре и разрежают у края.", "claims": ["c1", "c2"]},
  "data_meaning": {
    "inputs": [
      {"text": "Положение скважин относительно сводовой части залежи.", "claims": ["c2"], "hypothesis": false},
      {"text": "Параметры, полученные по скважинам; их достоверность растёт с числом скважин в центре.", "claims": ["c3"], "hypothesis": false},
      {"text": "Контур залежи и её приконтурная зона на карте.", "claims": ["c4"], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Сетка, густая в своде и редкая у края.", "claims": ["c2"], "hypothesis": false},
      {"text": "Более надёжные параметры для подсчёта запасов и проекта разработки.", "claims": ["c3"], "hypothesis": false},
      {"text": "Меньше бурения приконтурных скважин, малоэффективных для разведки.", "claims": ["c4"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Правило сформулировано как допущение о цели: освещать объём, а не площадь.", "claims": ["c1"], "hypothesis": false},
      {"text": "Если скважин в центре мало, параметры для подсчёта запасов ненадёжны.", "claims": ["c3"], "hypothesis": true},
      {"text": "Краевые скважины полезны для разработки, поэтому «малоэффективны» верно только для разведки.", "claims": ["c4", "c5"], "hypothesis": false}
    ]
  },
  "it_analogy": {
